// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadOswald = makeLoadFont('Oswald');
const loadInter = makeLoadFont('Inter');

// Module-level font loading ensures fonts are ready before frame 0
const { fontFamily: oswaldFamily } = loadOswald();
const { fontFamily: interFamily } = loadInter();



export type SpeakerTitlePopUpProps = Record<string, any>;

const SpeakerTitlePopUp: React.FC<SpeakerTitlePopUpProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 5,
  speakerName = "Jordan Davis",
  speakerRole = "Lead Designer",
  primaryColor = "#FF7A00",
  secondaryColor = "#FFFFFF",
  nameTextColor = "#FFFFFF",
  roleTextColor = "#FF7A00",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background logic extraction
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Frame timing calculations for a smooth staggered entrance and exit
  const totalFrames = durationInSeconds * fps;
  const exitStartRole = Math.max(20, totalFrames - 40);
  const exitStartName = Math.max(25, totalFrames - 30);

  // --- Smooth Animation Logic for Name Box ---
  // Adjusted spring config for a much smoother, classier ease-out (no bounce)
  const springConfig = { mass: 1.2, damping: 26, stiffness: 90 };

  const nameIn = spring({
    frame: frame - 10,
    fps,
    config: springConfig,
  });
  const nameOut = spring({
    frame: frame - exitStartName,
    fps,
    config: springConfig,
  });
  const nameProgress = Math.max(0, nameIn - nameOut);

  // --- Smooth Animation Logic for Role Box ---
  const roleIn = spring({
    frame: frame - 18, // Staggered entrance for elegance
    fps,
    config: springConfig,
  });
  const roleOut = spring({
    frame: frame - exitStartRole,
    fps,
    config: springConfig,
  });
  const roleProgress = Math.max(0, roleIn - roleOut);

  // --- Interpolations ---
  // We use pure slide and fade instead of scale for a more premium feel
  const nameOpacity = interpolate(nameProgress, [0, 0.7], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const roleOpacity = interpolate(roleProgress, [0, 0.7], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const nameTranslateX = interpolate(nameProgress, [0, 1], [-60, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const roleTranslateX = interpolate(roleProgress, [0, 1], [-50, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // --- Dynamic Styles ---
  const nameBoxStyle: React.CSSProperties = {
    backgroundColor: primaryColor,
    padding: `${height * 0.015}px ${width * 0.025}px`,
    borderRadius: 4, // Sharper, cleaner edges
    boxShadow: "0px 20px 50px rgba(0,0,0,0.1)", // Softer, more diffuse shadow
    transform: `translateX(${nameTranslateX}px)`,
    opacity: nameOpacity,
    transition: "none",
    maxWidth: width * 0.6,
  };

  const roleBoxStyle: React.CSSProperties = {
    backgroundColor: secondaryColor,
    padding: `${height * 0.012}px ${width * 0.02}px`,
    borderRadius: 4,
    boxShadow: "0px 20px 50px rgba(0,0,0,0.1)",
    transform: `translateX(${roleTranslateX}px)`,
    opacity: roleOpacity,
    transition: "none",
    maxWidth: width * 0.5,
  };

  const nameTextStyle: React.CSSProperties = {
    fontFamily: oswaldFamily,
    fontSize: width * 0.045,
    fontWeight: 700,
    textTransform: "uppercase",
    color: nameTextColor,
    margin: 0,
    lineHeight: 1.1,
    letterSpacing: 1, // Slight breathing room for elegance
    overflowWrap: "break-word",
    transition: "none",
  };

  const roleTextStyle: React.CSSProperties = {
    fontFamily: interFamily,
    fontSize: width * 0.025,
    fontWeight: 500,
    color: roleTextColor,
    margin: 0,
    lineHeight: 1.2,
    letterSpacing: 1.5,
    overflowWrap: "break-word",
    transition: "none",
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        transition: "none",
      }}
    >
      <div
        style={{
          position: "absolute",
          bottom: height * 0.1, // 10% from bottom edge safe zone
          left: width * 0.08, // 8% from left edge safe zone
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-start",
          gap: 4,
        }}
      >
        {/* Name Box */}
        <div style={nameBoxStyle}>
          <h1 style={nameTextStyle}>{speakerName}</h1>
        </div>

        {/* Role Box */}
        <div style={roleBoxStyle}>
          <h2 style={roleTextStyle}>{speakerRole}</h2>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default SpeakerTitlePopUp;